3	use std::io::{self, BufRead, BufReader, Read, Write};
4	use std::net::{SocketAddr, TcpListener, TcpStream};
5	use std::sync::Arc;
6	use std::thread;
7	
8	use crate::handlers::{App, Request, Response};
9	
10	/// 요청 머리(요청 줄부터 빈 줄까지, CRLF 포함) 한도. 기준 서버(uvicorn + h11)에서 실측한 경계
11	/// (verify/probe_head_limit.py: 127973 바이트는 받고 127974 바이트는 400)
12	const MAX_HEAD: usize = 127_973;
13	const STACK_SIZE: usize = 64 * 1024 * 1024;
14	
15	struct Parsed {
16	    method: String,
17	    target: Vec<u8>,
18	    headers: Vec<(String, Vec<u8>)>,
19	    body: Vec<u8>,
20	    keep_alive: bool,
21	    expect_continue: bool,
22	}
23	
24	enum ReadError {
25	    /// 연결이 닫혔거나 읽기 실패
26	    Closed,
27	    /// 잘못된 요청 줄·헤더 → 400 후 닫기
28	    Invalid,
29	    /// 잘못된 chunked 본문 → 400(chunked) 후 닫기
30	    InvalidBody,
31	}
32	
33	impl From<io::Error> for ReadError {
34	    fn from(_: io::Error) -> Self {
35	        ReadError::Closed
36	    }
37	}
38	
39	pub fn serve(listener: TcpListener, app: Arc<App>) {
40	    for stream in listener.incoming() {
41	        let Ok(stream) = stream else { continue };
42	        let app = Arc::clone(&app);
43	        // JSON 해석이 재귀라 깊은 중첩(pyjson::MAX_DEPTH)을 견딜 스택을 준다
44	        let spawned = thread::Builder::new()
45	            .stack_size(STACK_SIZE)
46	            .spawn(move || {
47	                let _ = connection(stream, &app);
48	            });
49	        drop(spawned);
50	    }
51	}
52	
53	fn connection(stream: TcpStream, app: &App) -> io::Result<()> {
54	    let local = stream.local_addr()?;
55	    let _ = stream.set_nodelay(true);
56	    let mut reader = BufReader::new(stream.try_clone()?);
57	    let mut writer = stream;
58	    loop {
59	        let read = read_head(&mut reader).and_then(|(mut request, framing)| {
60	            // uvicorn 은 본문을 읽는 라우트에서만 100 Continue 를 보낸다
61	            if request.expect_continue && app.reads_body(&request.method, &request.target) {
62	                writer.write_all(b"HTTP/1.1 100 Continue\r\n\r\n")?;
63	            }
64	            request.body = read_body(&mut reader, framing)?;
65	            Ok(request)
66	        });
67	        match read {
68	            Ok(request) => {
69	                let response = handle(app, &request, local);
70	                let head_only = request.method == "HEAD";
71	                write_response(&mut writer, &response, head_only, request.keep_alive)?;
72	                if !request.keep_alive {
73	                    return Ok(());
74	                }
75	            }
76	            Err(ReadError::Closed) => return Ok(()),
77	            Err(ReadError::Invalid) => {
78	                // 헤더 단계 오류: uvicorn 은 content-length 없이 보내고 연결을 닫는다
79	                writer.write_all(&invalid_request(false))?;
80	                return writer.flush();
81	            }
82	            Err(ReadError::InvalidBody) => {
83	                // 본문 단계 오류: h11 이 chunked 로 보낸다
84	                writer.write_all(&invalid_request(true))?;
85	                return writer.flush();
86	            }
87	        }
88	    }
89	}
90	
91	fn handle(app: &App, request: &Parsed, local: SocketAddr) -> Response {
92	    let req = Request {
93	        method: &request.method,
94	        target: &request.target,
95	        headers: &request.headers,
96	        body: &request.body,
97	        local,
98	    };
99	    // 처리 중 패닉은 Python 의 처리되지 않은 예외처럼 500 으로 바꾼다
100	    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| app.handle(&req)))
101	        .unwrap_or_else(|_| Response::internal_error())
102	}
103	
104	fn read_line(reader: &mut impl BufRead, budget: &mut usize) -> Result<Vec<u8>, ReadError> {
105	    let mut line = Vec::new();
106	    let read = reader
107	        .by_ref()
108	        .take(*budget as u64 + 1)
109	        .read_until(b'\n', &mut line)?;
110	    if read == 0 {
111	        return Err(ReadError::Closed);
112	    }
113	    if read > *budget {
114	        return Err(ReadError::Invalid);
115	    }
116	    *budget -= read;
117	    if line.pop() != Some(b'\n') {
118	        return Err(ReadError::Closed);
119	    }
120	    if line.last() == Some(&b'\r') {
121	        line.pop();
122	    }
123	    Ok(line)
124	}
125	
126	fn is_token(s: &[u8]) -> bool {
127	    !s.is_empty()
128	        && s.iter()
129	            .all(|&c| c.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&c))
130	}
131	
132	fn invalid_request(chunked: bool) -> Vec<u8> {
133	    const BODY: &str = "Invalid HTTP request received.";
134	    let head = "HTTP/1.1 400 Bad Request\r\ncontent-type: text/plain; charset=utf-8\r\nconnection: close\r\n";
135	    if chunked {
136	        format!(
137	            "{head}transfer-encoding: chunked\r\n\r\n{:x}\r\n{BODY}\r\n0\r\n\r\n",
138	            BODY.len()
139	        )
140	    } else {
141	        format!("{head}\r\n{BODY}")
142	    }
143	    .into_bytes()
144	}
145	
146	enum Framing {
147	    None,
148	    Length(usize),
149	    Chunked,
150	}
151	
152	fn read_body(reader: &mut impl BufRead, framing: Framing) -> Result<Vec<u8>, ReadError> {
153	    match framing {
154	        Framing::None => Ok(Vec::new()),
155	        Framing::Length(length) => {
156	            let mut body = vec![0; length];
157	            reader.read_exact(&mut body)?;
158	            Ok(body)
159	        }
160	        Framing::Chunked => read_chunked(reader),
161	    }
162	}
163	
164	/// `Content-Length` 값(쉼표 목록이면 모두 같아야 한다, h11)
165	fn content_length(values: &[&[u8]]) -> Result<usize, ReadError> {
166	    let mut found = None;
167	    for value in values {
168	        for part in value.split(|&c| c == b',') {
169	            let part = part.trim_ascii();
170	            if part.is_empty() || !part.iter().all(u8::is_ascii_digit) {
171	                return Err(ReadError::Invalid);
172	            }
173	            let n: usize = std::str::from_utf8(part)
174	                .ok()
175	                .and_then(|s| s.parse().ok())
176	                .ok_or(ReadError::Invalid)?;
177	            if found.is_some_and(|f| f != n) {
178	                return Err(ReadError::Invalid);
179	            }
180	            found = Some(n);
181	        }
182	    }
183	    found.ok_or(ReadError::Invalid)
184	}
185	
186	fn read_head(reader: &mut impl BufRead) -> Result<(Parsed, Framing), ReadError> {
187	    let mut budget = MAX_HEAD;
188	    let line = read_line(reader, &mut budget)?;
189	    let parts: Vec<&[u8]> = line.split(|&c| c == b' ').collect();
190	    let [method, target, version] = parts[..] else {
191	        return Err(ReadError::Invalid);
192	    };
193	    if !is_token(method)
194	        || target.is_empty()
195	        || !target.iter().all(|&c| (0x21..=0x7E).contains(&c))
196	        || version.len() != 8
197	        || !version.starts_with(b"HTTP/")
198	        || !version[5].is_ascii_digit()
199	        || version[6] != b'.'
200	        || !version[7].is_ascii_digit()
201	    {
202	        return Err(ReadError::Invalid);
203	    }
204	    // HTTP/1.1 이상이면 keep-alive, Host 필수(h11)
205	    let http11 = (version[5], version[7]) >= (b'1', b'1');
206	    let mut headers: Vec<(String, Vec<u8>)> = Vec::new();
207	    loop {
208	        let line = read_line(reader, &mut budget).map_err(|e| match e {
209	            ReadError::Closed => ReadError::Invalid,
210	            other => other,
211	        })?;
212	        if line.is_empty() {
213	            break;
214	        }
215	        // obs-fold: 앞 헤더 값에 공백 하나로 이어 붙인다
216	        if line[0] == b' ' || line[0] == b'\t' {
217	            let (_, value) = headers.last_mut().ok_or(ReadError::Invalid)?;
218	            if line.iter().any(|&c| matches!(c, 0 | 0x0B | 0x0C)) {
219	                return Err(ReadError::Invalid);
220	            }
221	            value.push(b' ');
222	            value.extend_from_slice(line.trim_ascii());
223	            continue;
224	        }
225	        let colon = line
226	            .iter()
227	            .position(|&c| c == b':')
228	            .ok_or(ReadError::Invalid)?;
229	        let name = &line[..colon];
230	        if !is_token(name) {
231	            return Err(ReadError::Invalid);
232	        }
233	        let value = line[colon + 1..].trim_ascii();
234	        if value
235	            .iter()
236	            .any(|&c| matches!(c, 0 | b'\n' | b'\r' | 0x0B | 0x0C))
237	        {
238	            return Err(ReadError::Invalid);
239	        }
240	        headers.push((
241	            String::from_utf8_lossy(name).to_ascii_lowercase(),
242	            value.to_vec(),
243	        ));
244	    }
245	    let values = |name: &str| -> Vec<&[u8]> {
246	        headers
247	            .iter()
248	            .filter(|(n, _)| n == name)
249	            .map(|(_, v)| v.as_slice())
250	            .collect()
251	    };
252	    let close = values("connection").iter().any(|v| {
253	        v.split(|&c| c == b',')
254	            .any(|t| t.trim_ascii().eq_ignore_ascii_case(b"close"))
255	    });
256	    let hosts = values("host").len();
257	    if hosts > 1 || (http11 && hosts == 0) {
258	        return Err(ReadError::Invalid);
259	    }
260	    let expect_continue = http11
261	        && values("expect")
262	            .iter()
263	            .any(|v| v.eq_ignore_ascii_case(b"100-continue"));
264	    let transfer = values("transfer-encoding");
265	    let lengths = values("content-length");
266	    // Transfer-Encoding 이 있으면 Content-Length 는 무시한다(h11)
267	    let framing = if !transfer.is_empty() {
268	        if transfer.len() != 1 || !transfer[0].eq_ignore_ascii_case(b"chunked") {
269	            return Err(ReadError::Invalid);
270	        }
271	        Framing::Chunked
272	    } else if !lengths.is_empty() {
273	        Framing::Length(content_length(&lengths)?)
274	    } else {
275	        Framing::None
276	    };
277	    let parsed = Parsed {
278	        method: String::from_utf8_lossy(method).into_owned(),
279	        target: target.to_vec(),
280	        headers,
281	        body: Vec::new(),
282	        keep_alive: http11 && !close,
283	        expect_continue,
284	    };
285	    Ok((parsed, framing))
286	}
287	
288	fn read_chunked(reader: &mut impl BufRead) -> Result<Vec<u8>, ReadError> {
289	    let mut body = Vec::new();
290	    loop {
291	        let mut budget = MAX_HEAD;
292	        let line = read_line(reader, &mut budget)?;
293	        let size_text = line
294	            .split(|&c| c == b';')
295	            .next()
296	            .unwrap_or(&[])
297	            .trim_ascii();
298	        let size = std::str::from_utf8(size_text)
299	            .ok()
300	            .filter(|s| !s.is_empty() && s.len() <= 20)
301	            .and_then(|s| usize::from_str_radix(s, 16).ok())
302	            .ok_or(ReadError::InvalidBody)?;
303	        if size == 0 {
304	            // 트레일러를 빈 줄까지 버린다
305	            loop {
306	                if read_line(reader, &mut budget)?.is_empty() {
307	                    return Ok(body);
308	                }
309	            }
310	        }
311	        let start = body.len();
312	        body.resize(start + size, 0);
313	        reader.read_exact(&mut body[start..])?;
314	        // 조각 뒤에는 정확히 CRLF(h11 0.16)
315	        let mut footer = [0; 2];
316	        reader.read_exact(&mut footer)?;
317	        if &footer != b"\r\n" {
318	            return Err(ReadError::InvalidBody);
319	        }
320	    }
321	}
322	
323	fn reason(status: u16) -> &'static str {
324	    match status {
325	        200 => "OK",
326	        201 => "Created",
327	        204 => "No Content",
328	        307 => "Temporary Redirect",
329	        400 => "Bad Request",
330	        404 => "Not Found",
331	        405 => "Method Not Allowed",
332	        409 => "Conflict",
333	        422 => "Unprocessable Entity",
334	        _ => "Internal Server Error",
335	    }
336	}
337	
338	fn write_response(
339	    writer: &mut TcpStream,
340	    response: &Response,
341	    head_only: bool,
342	    keep_alive: bool,
343	) -> io::Result<()> {
344	    let mut head = format!(
345	        "HTTP/1.1 {} {}\r\n",
346	        response.status,
347	        reason(response.status)
348	    );
349	    if response.status != 204 {
350	        head.push_str(&format!("content-length: {}\r\n", response.body.len()));
351	    }
352	    if let Some(content_type) = response.content_type {
353	        head.push_str(&format!("content-type: {content_type}\r\n"));
354	    }
355	    if let Some(location) = &response.location {
356	        head.push_str(&format!("location: {location}\r\n"));
357	    }
358	    if let Some(allow) = response.allow {
359	        head.push_str(&format!("allow: {allow}\r\n"));
360	    }
361	    if !keep_alive {
362	        head.push_str("connection: close\r\n");
363	    }
364	    head.push_str("\r\n");
365	    let mut out = head.into_bytes();
366	    if !head_only {
367	        out.extend_from_slice(&response.body);
368	    }
369	    writer.write_all(&out)?;
370	    writer.flush()
371	}
